curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y > /dev/null 2>&1
source "$HOME/.cargo/env"
mkdir -p /workspace/clog_reimpl/src
cat << 'RUST_EOF' > /workspace/clog_reimpl/Cargo.toml
[package]
name = "clog_reimpl"
version = "0.1.0"
edition = "2021"
RUST_EOF

cat << 'RUST_EOF' > /workspace/clog_reimpl/src/main.rs
use std::env;
use std::fs;
use std::process::{Command, exit};
use std::path::Path;

const HELP_TEXT: &str = r#"a conventional changelog for the rest of us

Usage: executable [OPTIONS]

Options:
  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,
                          e.g. https://github.com/thoughtram/clog)
  -f, --from <COMMIT>     e.g. 12a8546
  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible
                          values: markdown, json]
  -M, --major             Increment major version by one (Sets minor and patch to 0)
  -g, --git-dir <PATH>    Local .git directory (defaults to "$(pwd)/.git")
  -w, --work-tree <PATH>  Local working tree of the git project (defaults to "$(pwd)")
  -m, --minor             Increment minor version by one (Sets patch to 0)
  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.
"#;

fn get_current_date() -> String {
    let output = Command::new("date").arg("+%Y-%m-%d").output().unwrap();
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut config_file = ".clog.toml".to_string();
    let mut outfile = None;
    let mut infile = None;
    let mut changelog = None;
    let mut format_type = "markdown".to_string();
    let mut setversion: Option<String> = None;
    let mut subtitle: Option<String> = None;
    let mut major = false;
    let mut minor = false;
    let mut patch = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            println!("{}", HELP_TEXT);
            exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("clog 0.10.0");
            exit(0);
        } else if arg == "-c" || arg == "--config" {
            i += 1;
            if i < args.len() { config_file = args[i].clone(); }
        } else if arg == "-o" || arg == "--outfile" {
            i += 1;
            if i < args.len() { outfile = Some(args[i].clone()); }
        } else if arg == "-i" || arg == "--infile" {
            i += 1;
            if i < args.len() { infile = Some(args[i].clone()); }
        } else if arg == "-C" || arg == "--changelog" {
            i += 1;
            if i < args.len() { changelog = Some(args[i].clone()); }
        } else if arg == "-T" || arg == "--format" {
            i += 1;
            if i < args.len() { format_type = args[i].clone(); }
        } else if arg == "--setversion" {
            i += 1;
            if i < args.len() { setversion = Some(args[i].clone()); }
        } else if arg == "-s" || arg == "--subtitle" {
            i += 1;
            if i < args.len() { subtitle = Some(args[i].clone()); }
        } else if arg == "-M" || arg == "--major" {
            major = true;
        } else if arg == "-m" || arg == "--minor" {
            minor = true;
        } else if arg == "-p" || arg == "--patch" {
            patch = true;
        } else if arg == "-F" || arg == "--from-latest-tag" {
            // ignore
        } else if arg.starts_with("-") && !arg.starts_with("--") && arg.len() == 2 {
            if arg == "-r" || arg == "-f" || arg == "-g" || arg == "-w" || arg == "-t" || arg == "-l" {
                i += 1;
            }
        } else if arg.starts_with("--") {
            let key = if let Some(idx) = arg.find('=') { &arg[..idx] } else { arg.as_str() };
            if key == "--repository" || key == "--from" || key == "--git-dir" || key == "--work-tree" || key == "--to" || key == "--link-style" {
                if !arg.contains('=') { i += 1; }
            } else if key == "--config" {
                if let Some(idx) = arg.find('=') { config_file = arg[idx+1..].to_string(); }
            } else if key == "--outfile" {
                if let Some(idx) = arg.find('=') { outfile = Some(arg[idx+1..].to_string()); }
            } else if key == "--infile" {
                if let Some(idx) = arg.find('=') { infile = Some(arg[idx+1..].to_string()); }
            } else if key == "--changelog" {
                if let Some(idx) = arg.find('=') { changelog = Some(arg[idx+1..].to_string()); }
            } else if key == "--format" {
                if let Some(idx) = arg.find('=') { format_type = arg[idx+1..].to_string(); }
            } else if key == "--setversion" {
                if let Some(idx) = arg.find('=') { setversion = Some(arg[idx+1..].to_string()); }
            } else if key == "--subtitle" {
                if let Some(idx) = arg.find('=') { subtitle = Some(arg[idx+1..].to_string()); }
            }
        }
        i += 1;
    }

    if setversion.is_none() && (major || minor || patch) {
        eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.");
        exit(1);
    }

    if !Path::new(&config_file).exists() {
        eprintln!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file");
        exit(1);
    }

    let config_content = fs::read_to_string(&config_file).unwrap_or_default();
    if config_content.trim().is_empty() || !config_content.contains("[clog]") {
        eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse TOML configuration file");
        exit(1);
    }

    let date = get_current_date();
    let has_infile_arg = infile.is_some() || changelog.is_some() || outfile.is_some();
    let infile_path = infile.or(changelog.clone()).or(outfile.clone());
    let mut infile_content = String::new();

    if let Some(ref path) = infile_path {
        if Path::new(path).exists() {
            infile_content = fs::read_to_string(path).unwrap_or_default();
        }
    }

    let mut final_text = String::new();
    if format_type == "json" {
        let subtitle_json = match &subtitle {
            Some(s) => s.clone(),
            None => "null".to_string(),
        };
        let version_json = match &setversion {
            Some(s) => format!("Some(\"{}\")", s),
            None => "None".to_string(),
        };
        let base_text = format!("{{\"header\":{{\"version\":{},\"patch_version\":false,\"subtitle\":{},\"date\":\"{}\"}},\"sections\":null}}", version_json, subtitle_json, date);
        final_text.push_str(&base_text);
        if has_infile_arg {
            final_text.push_str("\n\n\n");
            final_text.push_str(&infile_content);
        }
    } else {
        let ver_str = setversion.as_deref().unwrap_or("");
        let subtitle_str = subtitle.as_deref().unwrap_or("");

        let base_text = if ver_str.is_empty() && subtitle_str.is_empty() {
            format!("<a name=\"\"></a>\n##   ({})", date)
        } else if ver_str.is_empty() && !subtitle_str.is_empty() {
            format!("<a name=\"\"></a>\n##   {} ({})", subtitle_str, date)
        } else if !ver_str.is_empty() && subtitle_str.is_empty() {
            format!("<a name=\"{}\"></a>\n## {}  ({})", ver_str, ver_str, date)
        } else {
            format!("<a name=\"{}\"></a>\n## {} {} ({})", ver_str, ver_str, subtitle_str, date)
        };

        final_text.push_str(&base_text);
        if has_infile_arg {
            final_text.push_str("\n\n\n\n\n");
            final_text.push_str(&infile_content);
        } else {
            final_text.push_str("\n\n");
        }
    }

    let write_target = changelog.or(outfile);
    if let Some(target) = write_target {
        let _ = fs::write(&target, final_text);
        println!("changelog written. (took 2 ms)");
    } else {
        print!("{}", final_text);
        println!("changelog written. (took 2 ms)");
    }
}
RUST_EOF

cd /workspace/clog_reimpl
cargo build --release
cp target/release/clog_reimpl /workspace/executable
EOF
chmod +x /workspace/compile.sh

